void present(const CheckpointResumeAdmission& r){check(r.status==CheckpointResumeAdmissionStatus::Prepared&&!r.replayed&&r.error.isEmpty()&&r.epoch&&!r.receiptUtf8.isEmpty(),"exact prepared resume state/readback is typed, not a fresh launch token");}
void held(Fixture& f){const auto before=f.db.dump();const auto r=f.read();check(r.status==CheckpointResumeAdmissionStatus::Held&&!r.error.isEmpty()&&r.error.size()<=512&&!r.epoch&&r.receiptUtf8.isEmpty()&&!r.replayed,"invalid/uncertain resume returns Held with no partial plausible admission");check(f.db.dump()==before,"Held read makes no mutation/repair/reprepare");}
void positive(){for(int depth:{1,3,72}){Fixture f(depth,depth==3,depth==1);const auto before=f.db.dump(),disk=storageHash(f.file);const auto r=f.read();present(r);check(r.receiptUtf8==f.prepared.receiptUtf8&&r.epoch->requestUUID==f.request&&r.epoch->observationUUID==Observation&&r.epoch->bookingId==f.booking&&r.epoch->run==f.newRun&&r.epoch->previousRun==f.base.run&&r.epoch->checkpoint.resume.start==First&&r.epoch->checkpoint.resume.end==plus(1),"real saved epoch retains original intent/range/lineage/wide counters");check(f.db.dump()==before&&storageHash(f.file)==disk,"both SQLite/WAL bytes and every record/date unchanged");const auto again=f.read();present(again);check(again.receiptUtf8==r.receiptUtf8&&again.epoch->predecessor==r.epoch->predecessor,"exact readback replay preserves predecessor (not retry permission)");BookingStore reopened(f.file);const auto other=reopened.savedPreparedCheckpointResumeAdmission(f.request,Device.toLower(),f.newRun,Observation,f.base);present(other);check(other.receiptUtf8==r.receiptUtf8&&f.db.dump()==before,"reopen remains read-only/identical");}
}
